  const aiPlanSiteLabel=type=>type==='air'?'قواعد طيران':type==='sea'?'قواعد/موانئ':type==='road'?'مراكز لوجستية':type==='power'?'مشروعات طاقة':type==='bank'?'فروع':'مواقع';
  const aiClamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  function aiAssetRole(type,item){const seg=String(item?.segment||''),sp=item?.specs||{};if(type==='air'){if(sp.cargo||seg.includes('شحن'))return 'cargo';if(seg.includes('تنفيذي')||seg.includes('VIP'))return 'executive';if(seg.includes('إقليمي'))return 'regional';return 'passenger';}if(type==='sea'){if(seg.includes('حاويات'))return 'container';if(seg.includes('غاز'))return 'lng';if(seg.includes('ناقلات'))return 'tanker';if(seg.includes('سائبة')||seg.includes('بضائع عامة'))return 'bulk';if(seg.includes('Ro-Ro'))return 'roro';if(seg.includes('سياحي'))return 'cruise';return 'support';}if(type==='road'){if(sp.refrigerated||seg.includes('تبريد'))return 'reefer';if(sp.container||seg.includes('حاويات'))return 'container';if(sp.tanker||seg.includes('صهريج'))return 'tanker';if(sp.electric||sp.hydrogen||sp.autonomous||seg.includes('كهربائي')||seg.includes('هيدروجين')||seg.includes('ذاتي'))return 'future';if(seg.includes('حضري')||seg.includes('توزيع'))return 'urban';if(seg.includes('تنفيذي'))return 'executive';return 'longhaul';}return 'general';}
  const aiRoleLabel=(type,role)=>({air:{cargo:'شحن',passenger:'ركاب/شبكة',regional:'إقليمي',executive:'تنفيذي/VIP'},sea:{container:'حاويات',lng:'غاز LNG/LPG',tanker:'ناقلات',bulk:'بضائع سائبة/عامة',roro:'Ro-Ro',cruise:'سياحي',support:'دعم/متخصص'},road:{longhaul:'نقل ثقيل/بعيد',container:'حاويات',reefer:'تبريد',urban:'حضري/توزيع',future:'كهربائي/هيدروجين/ذاتي',tanker:'صهاريج',executive:'دعم تنفيذي'}}[type]?.[role]||role);
  function aiPortfolioWeights(type,ctx){const e=ctx.state.realism?.economy||{},m=ctx.state.realism?.market||{},pressure=Number(m.competitorPressure?.[type]||50)/100;if(type==='air'){const cargo=aiClamp(.36+(Number(e.freight||100)-100)/280+(Number(e.airDemand||100)-100)/700,.24,.58),executive=aiClamp(.08+(Number(e.airDemand||100)-100)/1600-pressure*.015,.06,.14),regional=aiClamp(.12+pressure*.035,.10,.18),passenger=Math.max(.18,1-cargo-executive-regional);return {cargo,passenger,regional,executive};}if(type==='sea'){const container=aiClamp(.34+(Number(e.freight||100)-100)/350,.24,.48),energy=aiClamp(.22+(Number(e.oil||78)-78)/500,.14,.32),lng=energy*.48,tanker=energy*.52,bulk=.17,roro=.09,cruise=aiClamp(.05+(Number(e.seaDemand||100)-100)/1800,.03,.08),support=Math.max(.04,1-container-lng-tanker-bulk-roro-cruise);return {container,lng,tanker,bulk,roro,cruise,support};}if(type==='road'){const freight=aiClamp(.30+(Number(e.freight||100)-100)/450,.23,.40),container=freight*.48,longhaul=freight*.52,reefer=.18,urban=.16,future=aiClamp(.14+(Number(e.diesel||.98)-.98)*.10,.10,.22),tanker=.08,executive=.03;const scale=1/(container+longhaul+reefer+urban+future+tanker+executive);return {container:container*scale,longhaul:longhaul*scale,reefer:reefer*scale,urban:urban*scale,future:future*scale,tanker:tanker*scale,executive:executive*scale};}if(type==='power'){const gasPenalty=aiClamp((Number(e.gas||39)-39)/150,-.08,.10),demand=aiClamp((Number(e.powerDemand||100)-100)/500,-.05,.08);return {solar:aiClamp(.34+demand,.28,.42),wind:.24,storage:aiClamp(.20+demand,.16,.28),gas:aiClamp(.22-gasPenalty,.14,.30)};}if(type==='bank')return {corporate:.32,retail:.22,digital:.28,treasury:.18};return {general:1};}
  function aiLargestRemainder(total,weights){total=Math.max(0,Math.floor(Number(total)||0));const entries=Object.entries(weights),raw=entries.map(([k,w])=>[k,total*Math.max(0,Number(w)||0)]),out=Object.fromEntries(raw.map(([k,v])=>[k,Math.floor(v)]));let left=total-Object.values(out).reduce((a,b)=>a+b,0);raw.sort((a,b)=>(b[1]%1)-(a[1]%1)||a[0].localeCompare(b[0]));for(let i=0;i<left;i++)out[raw[i%raw.length][0]]++;return out;}
  function aiPortfolioMix(type,ctx,total){const weights=aiPortfolioWeights(type,ctx),target=aiLargestRemainder(total,weights);return {weights,target,generatedHour:Math.floor((ctx.state.simSeconds||0)/3600)};}
  function aiAssetEconomicScore(type,item,ctx){const sp=item?.specs||{},price=Math.max(1,Number(item?.price)||1),yieldM=Math.max(.5,Number(sp.yieldMultiplier)||1),rel=(Number(sp.reliability||sp.safety)||97)/100,demand=Number(ctx.state.realism?.economy?.[type==='air'?'airDemand':type==='sea'?'seaDemand':'roadDemand']||100)/100,capacity=Math.max(1,Number(sp.capacity)||1);let variable=1;if(type==='air')variable=Math.max(.5,1-(Number(sp.fuelBurnKgPerKm)||1)*.025-(Number(sp.maintenancePerFlightHour)||0)/120000);else if(type==='sea')variable=Math.max(.45,1-(Number(sp.fuelTonPerDay)||20)/350-(Number(sp.maintenancePerDay)||0)/600000);else variable=Math.max(.5,1-(Number(sp.fuelLPer100km)||0)/180-(Number(sp.maintenancePerKm)||.18)/4);return (capacity*yieldM*rel*demand*variable)/Math.pow(price/1e6,.72);}
  function aiPlanPortfolioSummary(type,ctx,p){if(!['air','sea','road'].includes(type)||!p.assetsTarget)return '';const mix=aiPortfolioMix(type,ctx,p.assetsTarget);return Object.entries(mix.target).filter(([,n])=>n>0).map(([r,n])=>`${aiRoleLabel(type,r)} ${n}`).join(' · ');}
  function aiPlanFor(state,type){const fallback=()=>state.advanced?.ai?.annualPlans?.[type]||{year:new Date(Date.UTC(2026,0,1)+(Number(state.simSeconds)||0)*1000).getUTCFullYear(),status:'draft',sitesTarget:0,capacityTarget:0,assetsTarget:0,budget:0,spent:0,regions:'عالمي',authorizedAtHour:null,masterLetterId:null};try{return globalThis.GH_AI_EXECUTIVE_CORE?.plan?.(state,type)||globalThis.GH_DOMAIN_COMMANDS?.dispatch?.({state},'ai','get-plan',{company:type},{actor:'ai-planner'})?.result||fallback();}catch{return fallback();}}
